local config = {
  ui_story_5032_50320101_1_dialog_content = "<color=#e8d9bb>คาร์ลีนผู้หลงทางกับการตามหาความแข็งแกร่ง เดินทางร่วมกับ PlayerName และไวซ์ เพื่อไปพักผ่อนที่เมืองฮาร์เบอร์</color>",
  ui_story_5032_50320101_2_dialog_content = "<color=#e8d9bb>ระหว่างทางไปเข้าพบเจ้าเมืองเอลวิส เคเลสไทต์ก็ได้พบกับนักสัตว์มหัศจรรย์วิทยาฟีญ่าอีกครั้ง</color>",
  ui_story_5032_50320101_3_dialog_content = "<color=#e8d9bb>เจ้าเมืองเอลวิสต้อนรับคณะเดินทางอย่างอบอุ่น แต่ดูเหมือนเขาจะปิดบังบางอย่างไว้เบื้องหลังร่างกายที่อ่อนแอและใบหน้าที่มีแผลเป็น</color>",
  ui_story_5032_50320101_4_dialog_content = "<color=#e8d9bb>โชคชะตาพลิกผันนำพาทุกคนมายังเรือมรกต ซึ่งเป็นสถานที่จัดงานเทศกาลครั้งใหญ่</color>",
  ui_story_5032_50320101_5_dialog_content = "<color=#e8d9bb>ณ ที่แห่งนี้ PlayerName กับคนอื่น ๆ ก็ได้พบกับเจโน่ หัวหน้าคณะละครสัตว์ผู้ลึกลับและไม่สุงสิงกับใคร</color>",
  ui_story_5032_50320101_6_dialog_content = "<color=#e8d9bb>เรนโบว์ผู้ร่าเริงและกระตือรือร้น พิธีกร ผู้ประสานงานลูกค้า หัวหน้าฝ่ายรักษาความปลอดภัย และวิศวกรทางทะเลฝึกหัด</color>",
  ui_story_5032_50320101_7_dialog_content = "<color=#e8d9bb>และพี่น้องนักแสดงชิงช้าเหินฟ้าสุดระทึกทั้ง 3 คน เมอรีลท์ ซับลี่ และฟริเม็ต</color>",
  ui_story_5032_50320101_8_dialog_content = "<color=#e8d9bb>ฟีญ่ามั่นใจว่าสัตว์มหัศจรรย์ที่เธอตามหา <color=#FFB400>วาฬเมฆา</color> จะต้องอยู่ที่ไหนซักแห่งในเรือมรกต</color>",
  ui_story_5032_50320101_9_dialog_content = "<color=#e8d9bb>เพื่อพิสูจน์ว่าข้อสันนิษฐานของเธอถูกต้อง กลุ่มของเคเลสไทต์จึงตัดสินใจสมัครเข้าร่วมงานแข่งขัน และประวิงเวลาเพื่อสำรวจคณะละครสัตว์</color>",
  ui_story_5032_50320101_10_dialog_content = "<color=#e8d9bb>ในขณะเดียวกัน คาร์ลีนที่ยังรู้สึกหลงทาง ก็ได้สอบถามไวซ์เกี่ยวกับพลังใหม่ที่ได้รับ</color>",
  ui_story_5032_50320101_11_dialog_content = "<color=#e8d9bb>เรือมรกตเต็มไปด้วยความรื่นเริงและเสียงหัวเราะ แต่เจ้าเมืองเอลวิสที่รับหน้าที่เป็นกรรมการ กลับจมอยู่ในความคิดของตัวเอง</color>",
  ui_story_5032_50320101_12_dialog_content = "<color=#e8d9bb>หลังจากเจอกับเรื่องผิดหวังในระหว่างการแข่ง คำพูดให้กำลังใจของ PlayerName ก็ทำให้คาร์ลีนได้รับมุมมองใหม่ๆ</color>",
  ui_story_5032_50320101_13_dialog_content = "<color=#e8d9bb>ท้ายที่สุดแล้ว ทีมเคเลสไทต์ก็คว้าชัยชนะมาได้ในที่สุด แต่รางวัลกลับไม่ใช่วาฬเมฆา</color>",
  ui_story_5032_50320101_14_dialog_content = "<color=#e8d9bb>รางวัลที่ว่านั้นคือไคโล สัตว์มหัศจรรย์คู่หูของฟีญ่า ซึ่งเธอมอบหมายให้ไปค้นหาวาฬเมฆาในทะเลบริเวณใกล้เคียง</color>",
  ui_story_5032_50320101_15_dialog_content = "<color=#e8d9bb>ด้วยความผิดหวัง กลุ่มของเคเลสไทต์จึงตัดสินใจบอกลาเจโน่เพื่อออกเดินทางตามหาวาฬเมฆาต่อไป</color>",
  ui_story_5032_50320101_16_dialog_content = "<color=#e8d9bb>แต่พอตามหาเจโน่ ก็พบว่าเขานอนหมดสติอยู่ภายในเรือมรกต</color>",
  ui_story_5032_50320101_17_dialog_content = "<color=#e8d9bb>ทันทีที่เจโน่ฟื้น เรือมรกตก็สั่นสะเทือนอย่างรุนแรง</color>",
  ui_story_5032_50320101_18_dialog_content = "<color=#e8d9bb>เจโน่รีบพาทีมลงไปยังห้องแกนกลางของเรือมรกต</color>",
  ui_story_5032_50320101_19_dialog_content = "<color=#e8d9bb>แต่ระหว่างทาง ยามที่มีตราประจำตระกูลเอลวิสปิดกั้นเส้นทางของพวกเขา</color>",
  ui_story_5032_50320101_20_dialog_content = "<color=#e8d9bb>หลังจากเอาชนะอุปสรรคมากมาย ในที่สุดคณะเดินทางของเคเลสไทต์ก็ไปถึงห้องแกนกลางได้สำเร็จ และพบเอลวิสที่นั่น</color>",
  ui_story_5032_50320101_21_dialog_content = "<color=#e8d9bb>เขาใช้อุปกรณ์บางอย่างในไม้เท้าของตัวเองเพื่อดูดพลังจากแกนพลังงาน</color>",
  ui_story_5032_50320101_22_dialog_content = "<color=#e8d9bb>การกระทำดังกล่าวทำให้ผู้พิทักษ์จักรกลขนาดยักษ์ที่ปกป้องแกนกลางตื่นขึ้นมา และเริ่มโจมตีทุกคน</color>",
  ui_story_5032_50320101_23_dialog_content = "<color=#e8d9bb>ผู้พิทักษ์อันทรงพลังเกือบทำให้ทีมโคลอสซัสต้องพ่ายแพ้ และคาร์ลีนก็ติดกับดักของเอลวิสทำให้สูญเสียพลังจนขยับไม่ได้</color>",
  ui_story_5032_50320101_24_dialog_content = "<color=#e8d9bb>แต่ในวินาทีแห่งความเป็นความตาย พลังใหม่ก็ได้ตื่นขึ้นในตัวของคาร์ลีน ทำให้เธอโต้กลับได้</color>",
  ui_story_5032_50320101_25_dialog_content = "<color=#e8d9bb>คณะเดินทางเอาชนะผู้พิทักษ์ได้ในที่สุด แม้เอลวิสจะหนีออกมาได้ แต่สุดท้ายก็ถูกผู้พิพากษาแมทธิวแห่งลูโมโพลิสจับตัวได้</color>",
  ui_story_5032_50320101_26_dialog_content = "<color=#e8d9bb>ดูเหมือนว่าเรื่องทุกอย่างนี้... ยังไม่จบลงง่าย ๆ อย่างแน่นอน</color>",
  ui_story_5032_50320101_27_dialog_content = "<color=#e8d9bb>อากาศคำรามในสายฝนที่หนาวเย็น และท้องฟ้าลุกเป็นไฟด้วยลมป่า พายุที่จะฉีกฮาร์เบอร์ซิตี้ออกจากกันกำลังจะมา!</color>",
  ui_story_5032_50320101_28_dialog_content = "เร็วสิ มาเร็ว! วิวตรงนี้สวยมากเลยนะ!",
  ui_story_5032_50320101_29_dialog_content = "อ-เอลวิส! นายวิ่งเร็วไปแล้ว!",
  ui_story_5032_50320101_30_dialog_content = "ว้าว...",
  ui_story_5032_50320101_31_dialog_content = "เป็นไง? ถ้าอยู่บ้านอย่างเดียว นายก็ไม่มีทางได้เห็นวิวแบบนี้หรอกนะ",
  ui_story_5032_50320101_32_dialog_content = "ไม่ต้องกลัวนักเลงเหลือขอพวกนั้นหรอก ถึงมันมากันเยอะกว่านั้นฉันก็จัดการไหว",
  ui_story_5032_50320101_33_dialog_content = "จากนี้ไป ชายหาดและทะเลแห่งจะเป็นของเราแค่สองคนเท่านั้น!",
  ui_story_5032_50320101_34_dialog_content = "อื้ม!",
  ui_story_5032_50320101_35_dialog_content = "บางทีฉันก็ฝันไว้ว่าจะทำแบบนี้ เดินออกจากห้องแล้ววาดภาพโลกภายนอก",
  ui_story_5032_50320101_36_dialog_content = "บางที... บางทีฉันควรจะวาดช่วงเวลานี้ของเรา",
  ui_story_5032_50320101_37_dialog_content = "จริงเหรอ? นายจะวาดภาพฉันจริง ๆ เหรอ?",
  ui_story_5032_50320101_38_dialog_content = "อื้ม... แต่ฉันวาดช้านะ แล้วก็ไม่ได้วาดเก่งขนาดนั้น...",
  ui_story_5032_50320101_39_dialog_content = "ไม่เป็นไร ภาพวาดของเจโน่น่ะ ดีที่สุดสำหรับฉันอยู่แล้ว!",
  ui_story_5032_50320101_40_dialog_content = "เอ่อ งั้นเราเจอกันพรุ่งนี้เช้าที่ท่าเรือนะ ตกลงมั้ย?",
  ui_story_5032_50320101_41_dialog_content = "เราไปจับปลาจากทะเลกัน เสร็จแล้วนายก็วาดภาพฉัน เดี๋ยวฉันทำซุปซีฟู้ดให้!",
  ui_story_5032_50320101_42_dialog_content = "ว้าว ซุปซีฟู้ดฝีมือเอลวิส!",
  ui_story_5032_50320101_43_dialog_content = "เยี่ยมเลย~ งั้นตกลงตามนี้!",
  ui_story_5032_50320101_44_dialog_content = "ได้!",
  ui_story_5032_50320101_45_dialog_content = "เราสัญญากันแล้ว...",
  ui_story_5032_50320101_46_dialog_content = "เราสัญญาแล้วว่าจะเจอกัน...",
  ui_story_5032_50320101_47_dialog_content = "ทำไมวันนั้นนายถึงจากฉันไปโดยที่ไม่ลาซักคำ?",
  ui_story_5032_50320101_48_dialog_content = "ทำไมนายถึงหักหลังฉัน? ทำลายบ้านของฉัน? และทำให้ฉันต้องผิดคำสาบานกับทรู ออเดอร์?",
  ui_story_5032_50320101_49_dialog_content = "แล้วทำไมนายถึง... เจ็บปวดแบบนั้น?",
  ui_story_5032_50320101_50_dialog_content = "บอส",
  ui_story_5032_50320101_51_dialog_content = "บอส!",
