  ui_story_5032_50320101_55_dialog_content = "ไม่มีอะไร ก็แค่คิดหาวิธีซ่อมเรือมรกตอยู่",
  ui_story_5032_50320101_56_dialog_content = "งั้นเหรอ? แต่คุณมอบหมายงานนั่นให้ฉันกับเซียลแล้วไม่ใช่หรือไง",
