  ui_story_5032_50320101_71_dialog_content = "ก็เลยจะไปซื้อเพิ่ม",
  ui_story_5032_50320101_72_dialog_content = "หา? อะไรนะ?",
  ui_story_5032_50320101_73_dialog_content = "ตรงที่คุณยืนอยู่ก็มีลูกโป่งเต็มลังไม่ใช่เหรอ...",
  ui_story_5032_50320101_74_dialog_content = "ผู้พิพากษา Matthieu ผู้ช่วยผู้พิพากษา Loewe",
  ui_story_5032_50320101_75_dialog_content = "ต้องขอโทษด้วยที่ให้พวกคุณรอ",
  ui_story_5032_50320101_76_dialog_content = "ฉันไม่นึกเลยว่างานในแต่ละวันของเอลวิสจะมากมายขนาดนี้",
  ui_story_5032_50320101_77_dialog_content = "ตอนนี้เขาเป็นยังไงบ้าง?",
  ui_story_5032_50320101_78_dialog_content = "ก็เหมือนเดิม ไม่ยอมกินข้าว ไม่แม้แต่จะดื่มน้ำ",
  ui_story_5032_50320101_79_dialog_content = "งั้นรึ? ช่างมีพลังใจที่น่าชื่นชมจริง ๆ",
  ui_story_5032_50320101_80_dialog_content = "เอ่อ ขอถามอะไรหน่อยนะ องค์หญิง ท่านคิดจะทำแบบนี้ไปอีกนานเท่าไหร่?",
  ui_story_5032_50320101_81_dialog_content = "เรารายงานสภาผู้อาวุโสไปตามที่ท่านบอกแล้ว แต่พวกนั้นคงไม่ปล่อยเราไปง่าย ๆ แน่",
  ui_story_5032_50320101_82_dialog_content = "เราต้องสืบหาแรงจูงใจที่แท้จริงของเอลวิสให้ได้โดยเร็ว เพื่อสะสางสิ่งที่เป็นต้นเหตุของการกบฏ",
  ui_story_5032_50320101_83_dialog_content = "ไม่งั้นพวกเรานี่แหละ ที่จะต้องติดร่างแหไปกับเรื่องยุ่งยากของเมืองฮาร์เบอร์ในครั้งนี้",
  ui_story_5032_50320101_84_dialog_content = "ตอนนี้ฝั่งลอร์ดชวาตส์ก็โกรธจัด ส่วนชาวเมืองฮาร์เบอร์ก็เพิ่งสูญเสียลอร์ดอันเป็นที่รัก ทั้งสองฝ่ายต่างก็ตึงเครียด",
  ui_story_5032_50320101_85_dialog_content = "ท่านควรหยุดแล้วกลับลูโมโพลิส จากนั้นให้ลอร์ดชวาตส์ส่งคนมาสืบสวนแทน",
  ui_story_5032_50320101_86_dialog_content = "ไม่มีทาง ข้อแรก ฉันจะไม่เลิกทำอะไรกลางคัน",
  ui_story_5032_50320101_87_dialog_content = "ข้อสอง ถ้าฉันทิ้งทุกอย่างไปแบบนี้",
  ui_story_5032_50320101_88_dialog_content = "จะมั่นใจได้ยังไง ว่าลอร์ดชวาตส์กับชาวเมืองฮาร์เบอร์จะได้รับคำตอบที่คู่ควร?",
  ui_story_5032_50320101_89_dialog_content = "ก็ได้ ก็ได้ครับ ผมเข้าใจแล้ว ลืมที่ผมพูดเถอะ",
  ui_story_5032_50320101_90_dialog_content = "แต่ถึงอย่างไรก็ตาม ฉันต้องขอขอบคุณมาก ๆ ผู้พิพากษาแมทธิว",
  ui_story_5032_50320101_91_dialog_content = "นาน ๆ ทีน่ะนะ",
  ui_story_5032_50320101_92_dialog_content = "หืม? อะไรกัน? ฉันก็พูดเรื่องมีประโยชน์เป็นเหมือนกันนะ",
  ui_story_5032_50320101_93_dialog_content = "อืม",
  ui_story_5032_50320101_94_dialog_content = "รอให้ฉันเขียนรายงานเสร็จก่อนเถอะ แล้วฉันจะสั่งสอนให้รู้สำนึก ว่าทำไมฉันถึงได้เป็นผู้พิพากษา ส่วนนายได้เป็นแค่ผู้ช่วย!",
  ui_story_5032_50320101_95_dialog_content = "เอาล่ะ ฉันคงต้องฝากหน้าที่สำคัญอย่างการปกป้องเอลวิสให้พวกคุณแล้ว",
