  ui_story_5032_50320401_51_dialog_content = "ไม่มีปัญหา ฉันว่าตรงโน้นยังมีหนังสือประวัติศาสตร์อีกนะ เดี๋ยวจะลองไปเช็กดู",
  ui_story_5032_50320401_52_dialog_content = "<color=#e8d9bb>หลังจากผ่านไปสักพัก</color>",
  ui_story_5032_50320401_53_dialog_content = "ฟู่ โอเค พวกนี้คือหนังสือทุกเล่มที่มีคำว่า \"ประวัติศาสตร์\" ในชื่อ แล้วก็เนื้อหาที่มันดู... เกี่ยวกับประวัติศาสตร์น่ะนะ",
