  ui_story_5032_50320401_60_dialog_content = "\"จากนั้นวิญญาณคั่งแค้นของอิคลิพไซท์ ก็กลายมาเป็นคำสาปคอยคุกคามทายาทของวีรชนเหล่านั้น\"",
