  ui_story_5032_50320401_64_dialog_content = "\"เมืองฮาร์เบอร์ได้รับการคุ้มครองจากวีรชนจากโบราณกาล จึงไม่ถูกแผ้วพานโดยอิคลิพไซท์\"",
