  ui_story_5032_50320602_26_dialog_content = "อิคลิพไซท์มีจำนวนมากเกินไป แล้วชายฝั่งก็ยาวเกินกว่าที่จะตั้งแนวป้องกันได้อย่างมีประสิทธิภาพ!",
