  ui_story_5032_50320701_3_dialog_content = "พื้นมีแต่น้ำทะเลกับเศษกระจกเต็มไปหมด ไม่มีอะไรจะแย่ไปกว่านี้แล้ว...",
  ui_story_5032_50320701_4_dialog_content = "เงินก็เอาไปซ่อมเรือหมดแล้ว จะจ้างคนทำความสะอาดก็ไม่ได้ จะให้เก็บกวาดเองฉันก็ไม่ไหว!",
